SELECT DISTINCT lead_id FROM (


            SELECT id AS lead_id FROM sale_lead
             WHERE deleted = 0 AND phone = #{phone}
              AND tenant_id = #{tenantId}
            UNION
            SELECT lead_id FROM lead_phone
             WHERE deleted = 0 AND phone = #{phone}
              AND tenant_id = #{tenantId}


            UNION
            SELECT id AS lead_id FROM sale_lead
             WHERE deleted = 0 AND open_id = #{openId}
              AND tenant_id = #{tenantId}
            UNION
            SELECT lead_id FROM lead_phone
             WHERE deleted = 0 AND open_id = #{openId}
              AND tenant_id = #{tenantId}


            UNION
            SELECT id AS lead_id FROM sale_lead
             WHERE deleted = 0 AND wechat = #{wechat}
              AND tenant_id = #{tenantId}
            UNION
            SELECT lead_id FROM lead_phone
             WHERE deleted = 0 AND wechat = #{wechat}
              AND tenant_id = #{tenantId}


            SELECT NULL AS lead_id FROM DUAL WHERE 1=0


) t

